import * as THREE from 'three';
import { createRoot } from 'react-dom/client';
import React from 'react';
import html2canvas from 'html2canvas';
import { CassetteTape } from './CassetteTape';
import { Tape } from './types';

const cache = new Map<string, THREE.Texture>();
const pending = new Map<string, Promise<THREE.Texture>>();
let active = 0;
const MAX_CONCURRENT = 3;
const queue: (() => void)[] = [];

function cacheKey(tape: Tape): string {
  return `${tape.id}:${tape.tapeStyle}`;
}

function runNext() {
  while (active < MAX_CONCURRENT && queue.length > 0) {
    const next = queue.shift()!;
    next();
  }
}

function renderTapeTexture(tape: Tape): Promise<THREE.Texture> {
  const key = cacheKey(tape);
  const cached = cache.get(key);
  if (cached) return Promise.resolve(cached);
  const inflight = pending.get(key);
  if (inflight) return inflight;

  const promise = new Promise<THREE.Texture>((resolve) => {
    function start() {
      active++;
      const container = document.createElement('div');
      container.style.position = 'fixed';
      container.style.left = '-9999px';
      container.style.top = '-9999px';
      document.body.appendChild(container);

      const root = createRoot(container);
      root.render(React.createElement(CassetteTape, { tape }));

      setTimeout(async () => {
        try {
          const canvas = await html2canvas(container, {
            backgroundColor: null,
            scale: 2,
            useCORS: true,
          });
          const tex = new THREE.CanvasTexture(canvas);
          tex.colorSpace = THREE.SRGBColorSpace;
          tex.needsUpdate = true;
          cache.set(key, tex);
          resolve(tex);
        } catch (e) {
          console.error('Tape texture render failed:', e);
          // Return a placeholder texture
          const c = document.createElement('canvas');
          c.width = 468; c.height = 286;
          const ctx = c.getContext('2d')!;
          ctx.fillStyle = '#333';
          ctx.fillRect(0, 0, 468, 286);
          const tex = new THREE.CanvasTexture(c);
          tex.colorSpace = THREE.SRGBColorSpace;
          resolve(tex);
        } finally {
          try { root.unmount(); } catch {}
          try { document.body.removeChild(container); } catch {}
          active--;
          pending.delete(key);
          runNext();
        }
      }, 300);
    }

    if (active < MAX_CONCURRENT) {
      start();
    } else {
      queue.push(start);
    }
  });

  pending.set(key, promise);
  return promise;
}

export { renderTapeTexture, cache as textureCache };
