import React, { useMemo } from 'react';
import { RigidBody, CuboidCollider } from '@react-three/rapier';
import * as THREE from 'three';
import { useLoader } from '@react-three/fiber';
import { TABLE_W, TABLE_H } from './coords';

const WALL_HEIGHT = 2;
const WALL_THICKNESS = 0.5;

export function TableSurface() {
  const woodTexture = useLoader(THREE.TextureLoader, '/table-wood.jpg');

  const material = useMemo(() => {
    woodTexture.wrapS = woodTexture.wrapT = THREE.RepeatWrapping;
    woodTexture.repeat.set(TABLE_W / 6, TABLE_H / 6);
    woodTexture.colorSpace = THREE.SRGBColorSpace;
    return new THREE.MeshStandardMaterial({
      map: woodTexture,
      roughness: 0.85,
      metalness: 0.0,
      color: '#8a7050',
    });
  }, [woodTexture]);

  return (
    <group>
      {/* Table surface — static rigid body */}
      <RigidBody type="fixed" colliders={false}>
        <CuboidCollider args={[TABLE_W / 2, 0.5, TABLE_H / 2]} position={[0, -0.5, 0]} />
        <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
          <planeGeometry args={[TABLE_W, TABLE_H]} />
          <primitive object={material} attach="material" />
        </mesh>
      </RigidBody>

      {/* Edge walls — invisible colliders to keep tapes on the table */}
      <RigidBody type="fixed" colliders={false}>
        {/* North wall */}
        <CuboidCollider args={[TABLE_W / 2, WALL_HEIGHT / 2, WALL_THICKNESS / 2]} position={[0, WALL_HEIGHT / 2, -TABLE_H / 2 - WALL_THICKNESS / 2]} />
        {/* South wall */}
        <CuboidCollider args={[TABLE_W / 2, WALL_HEIGHT / 2, WALL_THICKNESS / 2]} position={[0, WALL_HEIGHT / 2, TABLE_H / 2 + WALL_THICKNESS / 2]} />
        {/* West wall */}
        <CuboidCollider args={[WALL_THICKNESS / 2, WALL_HEIGHT / 2, TABLE_H / 2]} position={[-TABLE_W / 2 - WALL_THICKNESS / 2, WALL_HEIGHT / 2, 0]} />
        {/* East wall */}
        <CuboidCollider args={[WALL_THICKNESS / 2, WALL_HEIGHT / 2, TABLE_H / 2]} position={[TABLE_W / 2 + WALL_THICKNESS / 2, WALL_HEIGHT / 2, 0]} />
      </RigidBody>

      {/* Dark overlay to match 2D look */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.001, 0]}>
        <planeGeometry args={[TABLE_W, TABLE_H]} />
        <meshBasicMaterial color="#000000" transparent opacity={0.45} />
      </mesh>
    </group>
  );
}
