import React, { useRef, useState, useEffect, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import { Html } from '@react-three/drei';
import { RigidBody, CuboidCollider, RapierRigidBody } from '@react-three/rapier';
import * as THREE from 'three';
import { Tape } from './types';
import { TAPE_W, TAPE_H, TAPE_D, DRAG_HEIGHT, to3D } from './coords';
import { renderTapeTexture } from './textureCache';

// Matches DragState in coords.ts — inlined to avoid bundler issues
interface DragState {
  tapeId: string | null;
  targetX: number;
  targetZ: number;
}

interface TapeBodyProps {
  tape: Tape;
  drag: DragState; // shared mutable object — read in useFrame, no re-renders
  menuOpen?: boolean;
  onMenuAction?: (tapeId: string, action: 'link' | 'rewind' | 'remove') => void;
  isNew?: boolean;
}

export function TapeBody({
  tape, drag, menuOpen, onMenuAction, isNew,
}: TapeBodyProps) {
  const bodyRef = useRef<RapierRigidBody>(null);
  const meshRef = useRef<THREE.Mesh>(null);
  const [texture, setTexture] = useState<THREE.Texture | null>(null);
  const wasDragging = useRef(false);
  const smoothPos = useRef({ x: 0, z: 0 });
  const velocity = useRef({ x: 0, z: 0 });

  // Load texture
  useEffect(() => {
    renderTapeTexture(tape).then(setTexture);
  }, [tape.id, tape.tapeStyle]);

  // Initial position from 2D coords
  const [x3d, z3d] = useMemo(() => to3D(tape.x ?? 500, tape.y ?? 500), [tape.x, tape.y]);
  const spawnY = isNew ? 5 : TAPE_D / 2 + 0.01;
  const angleRad = ((tape.angle ?? 0) * Math.PI) / 180;

  // Materials
  const materials = useMemo(() => {
    const side = new THREE.MeshStandardMaterial({ color: '#1a1a1a', roughness: 0.8 });
    if (!texture) {
      const placeholder = new THREE.MeshStandardMaterial({ color: '#333' });
      return [side, side, side, side, placeholder, side];
    }
    const front = new THREE.MeshStandardMaterial({ map: texture, roughness: 0.6, metalness: 0.05 });
    const back = new THREE.MeshStandardMaterial({ color: '#222', roughness: 0.9 });
    return [side, side, side, side, front, back];
  }, [texture]);

  // Handle drag state transitions and kinematic movement with momentum
  useFrame((_, delta) => {
    const body = bodyRef.current;
    if (!body) return;
    const isDragged = drag.tapeId === tape.id;

    if (isDragged) {
      if (!wasDragging.current) {
        wasDragging.current = true;
        body.setBodyType(1, true); // kinematic
        body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        body.setAngvel({ x: 0, y: 0, z: 0 }, true);
        // Initialize smooth position to current body position
        const t = body.translation();
        smoothPos.current.x = t.x;
        smoothPos.current.z = t.z;
        velocity.current.x = 0;
        velocity.current.z = 0;
      }

      // Lerp smooth position towards target — creates trailing momentum feel
      const lerp = 1 - Math.pow(0.001, delta); // ~0.12 per frame at 60fps
      const prevX = smoothPos.current.x;
      const prevZ = smoothPos.current.z;
      smoothPos.current.x += (drag.targetX - smoothPos.current.x) * lerp;
      smoothPos.current.z += (drag.targetZ - smoothPos.current.z) * lerp;

      // Track velocity for release momentum
      if (delta > 0) {
        velocity.current.x = (smoothPos.current.x - prevX) / delta;
        velocity.current.z = (smoothPos.current.z - prevZ) / delta;
      }

      body.setNextKinematicTranslation({
        x: smoothPos.current.x,
        y: DRAG_HEIGHT,
        z: smoothPos.current.z,
      });
    } else if (wasDragging.current) {
      wasDragging.current = false;
      body.setBodyType(0, true); // dynamic
      // Apply momentum from drag movement + downward drop
      const vx = velocity.current.x * 0.5;
      const vz = velocity.current.z * 0.5;
      body.setLinvel({ x: vx, y: -3, z: vz }, true);
      body.setAngvel({ x: vz * 0.5, y: 0, z: -vx * 0.5 }, true);
    }
  });

  return (
    <RigidBody
      ref={bodyRef}
      position={[x3d, spawnY, z3d]}
      rotation={[0, angleRad, 0]}
      type="dynamic"
      colliders={false}
      linearDamping={1.5}
      angularDamping={2}
      mass={0.5}
      restitution={0.15}
      friction={0.6}
      ccd={true}
    >
      <CuboidCollider args={[TAPE_W / 2, TAPE_D / 2, TAPE_H / 2]} />
      <mesh
        ref={meshRef}
        name={`tape-${tape.id}`}
        castShadow
        receiveShadow
        rotation={[-Math.PI / 2, 0, 0]}
      >
        <boxGeometry args={[TAPE_W, TAPE_H, TAPE_D]} />
        {materials.map((mat, i) => (
          <primitive key={i} object={mat} attach={`material-${i}`} />
        ))}
      </mesh>

      {/* Context menu */}
      {menuOpen && (
        <Html center position={[0, 0.5, TAPE_H / 2 + 0.3]} style={{ pointerEvents: 'auto' }}>
          <div style={{
            display: 'flex', gap: 6, whiteSpace: 'nowrap',
            transform: 'translateX(-50%)',
          }} onPointerDown={(e) => e.stopPropagation()}>
            <button
              onClick={(e) => {
                e.stopPropagation();
                const id = tape.isPlaylist ? tape.playlistId : tape.videoId;
                const url = `${window.location.origin}${window.location.pathname}?v=${id}&t=${tape.playlistIndex ?? 0}`;
                navigator.clipboard.writeText(url).then(() => {
                  (e.target as HTMLButtonElement).textContent = 'Copied!';
                  setTimeout(() => { (e.target as HTMLButtonElement).textContent = 'Link'; }, 1500);
                }).catch(() => { prompt('Copy this link:', url); });
              }}
              style={{ padding: '4px 10px', borderRadius: 6, border: 'none', background: '#3b82f6', color: '#fff', fontSize: 12, cursor: 'pointer', fontFamily: "'Courier New', monospace" }}
            >Link</button>
            <button
              onClick={(e) => { e.stopPropagation(); onMenuAction?.(tape.id, 'rewind'); }}
              style={{ padding: '4px 10px', borderRadius: 6, border: 'none', background: '#333', color: '#fff', fontSize: 12, cursor: 'pointer', fontFamily: "'Courier New', monospace" }}
            >Rewind</button>
            <button
              onClick={(e) => { e.stopPropagation(); onMenuAction?.(tape.id, 'remove'); }}
              style={{ padding: '4px 10px', borderRadius: 6, border: 'none', background: '#ef4444', color: '#fff', fontSize: 12, cursor: 'pointer', fontFamily: "'Courier New', monospace" }}
            >Remove</button>
          </div>
        </Html>
      )}
    </RigidBody>
  );
}
