// 2D canvas coords ↔ 3D world coords
// 2D canvas: 4000×2400, origin top-left
// 3D world: centered, y=up, tapes sit on y=0 plane

const CANVAS_W = 4000;
const CANVAS_H = 2400;
const SCALE = 100; // 100 2D pixels = 1 3D unit

export function to3D(x2d: number, y2d: number): [x: number, z: number] {
  return [
    (x2d - CANVAS_W / 2) / SCALE,
    (y2d - CANVAS_H / 2) / SCALE,
  ];
}

export function to2D(x3d: number, z3d: number): [x: number, y: number] {
  return [
    x3d * SCALE + CANVAS_W / 2,
    z3d * SCALE + CANVAS_H / 2,
  ];
}

// Tape dimensions in 3D units (234×143 px → 2.34×1.43 units)
export const TAPE_W = 2.34;
export const TAPE_H = 1.43;
export const TAPE_D = 0.24;

// Table dimensions in 3D
export const TABLE_W = CANVAS_W / SCALE; // 40
export const TABLE_H = CANVAS_H / SCALE; // 24

// Drag constants
export const DRAG_HEIGHT = 2;

// Shared mutable drag state — written by pointer handlers, read by TapeBody in useFrame
export interface DragState {
  tapeId: string | null;
  targetX: number;
  targetZ: number;
}
